module.TargetCode:
if (playerHealth >= 75)
{
    status = "Healthy";
}
else if (playerHealth > 0)
{
    status = "Hurt";
}
else
{
    status = "Defeated";
}

module.FillStarter:
if (playerHealth >= 75)
{
    status = "Healthy";
}
else if (playerHealth ___ 0)
{
    status = "Hurt";
}
else
{
    status = "Defeated";
}

module.TransferCode:
if (torchCount >= 5)
{
    status = "Full";
}
else if (torchCount > 0)
{
    status = "Low";
}
else
{
    status = "Empty";
}
